mapper.select:
select * from (select SUBJECT_NO subno, To_char(BALANCE_DATE,'yyyy-mm-dd hh:mm:ss') as valDate, (SELECT b.ACCT_SUBJECT_ID FROM BOK_BOOKSET b where b.BOOKSET_ID = BOK_BALANCE.BOOKSET_ID ) AS prodId, O_AMT cost from BOK_BALANCE where BOOKSET_ID in
#{item,jdbcType=VARCHAR}
and BALANCE_DATE = #{exeDate,jdbcType=TIMESTAMP} and SUBJECT_NO IN ('22210101','22210102','22210103','22210801','22210802','22210803') ) PIVOT ( MAX(cost) FOR subno IN ('22210101' AS additionalTaxCityBuild , '22210102' AS educationFeePlus, '22210103' AS localEducationFeePlus, '22210801' AS interestIncomeTax, '22210802' AS dividendTax, '22210803' AS spreadIncomeTax))
